SELECT u.id
FROM users u
WHERE u.id::text = #{identity}
    OR u.email = #{identity}

SELECT COALESCE(MAX(RIGHT(i.doc_no, 4)::integer), 0)
FROM invoice i
WHERE i.user_id = #{userId}
    AND i.doc_type = #{docType}
    AND i.doc_no ~ ('^' || #{prefix} || '[0-9]{4}$')

INSERT INTO invoice (
    user_id, doc_type, doc_no, source_quote_id, title, content,
    supply_amount, vat_amount, total_amount
)
VALUES (
    #{userId}, #{docType}, #{docNo}, #{sourceQuoteId,jdbcType=BIGINT}, #{title},
    CAST(#{content} AS jsonb), #{supplyAmount}, #{vatAmount}, #{totalAmount}
)
RETURNING id
